const route = JSON.parse(query);
const intents = ['REGISTRAR_PEDIDO', 'CONSULTA_MENU', 'CONSULTA_DOCUMENTAL', 'RECLAMO_SOPORTE', 'UNKNOWN'];
const risks = ['LOW', 'MEDIUM', 'HIGH'];
if (!route || !intents.includes(route.intent) || !risks.includes(route.risk) || typeof route.confidence !== 'number' || !Number.isFinite(route.confidence) || route.confidence < 0 || route.confidence > 1) {
  throw new Error('Clasificación de voz inválida: se requiere intent, risk y confidence válidos.');
}
return JSON.stringify({ intent: route.intent, confidence: route.confidence, risk: route.risk });

const steps = $json.intermediateSteps;
if (!Array.isArray(steps) || steps.length !== 1 || steps[0].action?.tool !== 'Seleccionar_ruta_voz' || typeof steps[0].observation !== 'string') {
  throw new Error('El agente de voz debe invocar exactamente una vez la herramienta de selección de ruta.');
}
let route;
try {
  const observation = JSON.parse(steps[0].observation);
  if (Array.isArray(observation)) {
    if (observation.length !== 1 || typeof observation[0]?.response !== 'string') throw new Error('Resultado de herramienta inesperado.');
    route = JSON.parse(observation[0].response);
  } else {
    route = observation;
  }
} catch (error) {
  throw new Error('La herramienta de voz no devolvió una clasificación JSON válida.');
}
const intents = ['REGISTRAR_PEDIDO', 'CONSULTA_MENU', 'CONSULTA_DOCUMENTAL', 'RECLAMO_SOPORTE', 'UNKNOWN'];
const risks = ['LOW', 'MEDIUM', 'HIGH'];
if (!route || Array.isArray(route) || !intents.includes(route.intent) || !risks.includes(route.risk) || typeof route.confidence !== 'number' || !Number.isFinite(route.confidence) || route.confidence < 0 || route.confidence > 1) {
  throw new Error('La herramienta de voz devolvió una clasificación fuera del contrato.');
}
return [{ json: { output: JSON.stringify(route) } }];

const items = $input.all();
if (items.length <= 1) return items;
return [items[0]];

const original = String($('Entrada multicanal').first().json.mensaje ?? '');
const raw = $json.text ?? $json.output ?? $json.response ?? '';
let d;
try {
  d = typeof raw === 'object' && raw !== null
    ? raw
    : JSON.parse(String(raw).replace(/^```json\s*/i, '').replace(/```$/, '').trim());
} catch (error) {
  d = { intent: 'UNKNOWN', confidence: 0, risk: 'HIGH', requires_human: true };
}
const allowed = ['REGISTRAR_PEDIDO', 'CONSULTA_MENU', 'CONSULTA_DOCUMENTAL', 'RECLAMO_SOPORTE', 'UNKNOWN'];
const intent = allowed.includes(d.intent) ? d.intent : 'UNKNOWN';
const confidenceValue = Number(d.confidence);
const confidence = Number.isFinite(confidenceValue) ? Math.max(0, Math.min(1, confidenceValue)) : 0;
const modelRisk = ['LOW', 'MEDIUM', 'HIGH'].includes(d.risk) ? d.risk : 'HIGH';
const normalized = original.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const criticalRules = [
  ['SALUD_Y_SEGURIDAD', /\b(alerg\w*|anafilax\w*|intoxic\w*|envenen\w*|cuerpo extrano|objeto extrano|vidrio|cristal roto|plastico en|metal en|contaminacion cruzada|me enferme por|me intoxique)\b/],
  ['DINERO_FRAUDE_O_COBRO', /\b(reembols\w*|devoluci\w*|reintegro\w*|reintegr\w*|devuelvan el dinero|dinero de vuelta|compensaci\w*|cupon\w*|bonificacion\w*|fraude\w*|cobro duplicado|cargo duplicado|cobro indebido|cargo indebido|cobro no reconocido|cargo no reconocido)\b/],
  ['RECLAMO_LEGAL', /\b(demanda\w*|abogad\w*|denuncia\w*|reclamo legal|acciones legales|acciones judiciales|sernac|indecopi|tribunal)\b/],
  ['CAMBIO_O_CIERRE_DE_CASO', /\b(cancel\w*|anul\w*|cerr\w*|resolv\w*|modific\w*)\b.{0,50}\b(reclamo|pedido|orden|caso)\b|\b(reclamo|pedido|orden|caso)\b.{0,50}\b(cancel\w*|anul\w*|cerr\w*|resolv\w*|modific\w*)\b/],
];
const detected = criticalRules.find(([, pattern]) => pattern.test(normalized));
const criticalSignal = detected ? detected[0] : '';
const requiresHuman = Boolean(d.requires_human) || Boolean(criticalSignal) || intent === 'UNKNOWN' || confidence < 0.85 || modelRisk === 'HIGH';
const risk = criticalSignal || intent === 'UNKNOWN' || modelRisk === 'HIGH'
  ? 'HIGH'
  : requiresHuman && modelRisk === 'LOW'
    ? 'MEDIUM'
    : modelRisk;
let hitlReason = '';
if (criticalSignal) hitlReason = `Señal crítica detectada: ${criticalSignal}`;
else if (intent === 'UNKNOWN') hitlReason = 'Intención no reconocida; requiere clasificación humana.';
else if (confidence < 0.85) hitlReason = 'Confianza menor al umbral operativo de 0.85.';
else if (modelRisk === 'HIGH') hitlReason = 'El clasificador marcó riesgo alto.';
else if (d.requires_human) hitlReason = 'El clasificador solicitó supervisión humana.';
return [{
  json: {
    original_input: original,
    intent,
    confidence,
    risk,
    requires_human: requiresHuman,
    critical_signal: criticalSignal,
    hitl_reason: hitlReason,
  },
}];

const classification=$('Normalizar clasificacion Router').first().json;
const input=$('Entrada multicanal').first().json;
const expectedWorkers={REGISTRAR_PEDIDO:'PEDIDOS',CONSULTA_MENU:'CONSULTAS',RECLAMO_SOPORTE:'RECLAMOS',CONSULTA_DOCUMENTAL:'RAG_Documental',UNKNOWN:'ANFITRION'};
const expected=expectedWorkers[classification.intent];
return $input.all().map(item => {
  const actual=String(item.json.worker??'');
  const mismatch=!expected||actual!==expected;
  const reason=mismatch?`Incompatibilidad de worker: intención ${classification.intent??'desconocida'}, esperado ${expected??'no definido'}, recibido ${actual||'ausente'}.`:'';
