const output = $input.item.json;
let candidate = output.output ?? output.text ?? output;
if (typeof candidate === 'string') candidate = JSON.parse(candidate);
if (candidate && typeof candidate === 'object' && candidate.structuredOutput) candidate = candidate.structuredOutput;
if (candidate && typeof candidate === 'object' && candidate.output && typeof candidate.output === 'object') candidate = candidate.output;
const base = $('Juez - Preparar entrada').item.json;
const score = candidate?.exactitud_factual;
const allowed = ['APROBADO', 'CORREGIR', 'ESCALAR'];
let verdict = candidate?.estado_veredicto;
const critique = String(candidate?.critica ?? '').trim();
if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('AI Judge: exactitud_factual must be an integer from 1 to 5.');
if (!allowed.includes(verdict)) throw new Error('AI Judge: estado_veredicto is outside the schema.');
if (!critique) throw new Error('AI Judge: missing actionable critique.');
if (verdict === 'APROBADO' && score < 4) verdict = 'ESCALAR';
if (Number(base.judge_attempts ?? 0) >= 1 && verdict === 'CORREGIR') verdict = 'ESCALAR';
return { json: { ...base, exactitud_factual: score, estado_veredicto: verdict, critica: critique } };

