const base = $('Juez - Preparar reintento').item.json;
const score = candidate?.exactitud_factual;
const allowed = ['APROBADO', 'CORREGIR', 'ESCALAR'];
let verdict = candidate?.estado_veredicto;
const critique = String(candidate?.critica ?? '').trim();
if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('AI Judge retry: exactitud_factual must be an integer from 1 to 5.');
if (!allowed.includes(verdict)) throw new Error('AI Judge retry: estado_veredicto is outside the schema.');
if (!critique) throw new Error('AI Judge retry: missing actionable critique.');
if (verdict === 'APROBADO' && score < 4) verdict = 'ESCALAR';
if (verdict === 'CORREGIR') verdict = 'ESCALAR';
return { json: { ...base, exactitud_factual: score, estado_veredicto: verdict, critica: critique } };
